import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Button, ListGroup, ListGroupItem } from 'reactstrap';
import ContractModal from './ContractModal';

const ProposalListModal = ({ isOpen, toggle, userId }) => {
    const [proposals, setProposals] = useState([]);
    const [isContractModalOpen, setIsContractModalOpen] = useState(false);

    useEffect(() => {
        if (isOpen && userId) {
            fetch(`http://localhost:8080/api/proposals/byUserId/${userId}`)
                .then((response) => response.json())
                .then((data) => {
                    console.log('Fetched proposals:', data);
                    if (Array.isArray(data)) {
                        setProposals(data);
                    } else {
                        setProposals([]);
                    }
                })
                .catch((error) => {
                    console.error('Error:', error);
                    setProposals([]);
                });
        }
    }, [isOpen, userId]);

    const toggleContractModal = () => setIsContractModalOpen(!isContractModalOpen);
    const refreshProposals = () => {
        if (userId) {
            fetch(`http://localhost:8080/api/proposals/byUserId/${userId}`)
                .then((response) => response.json())
                .then((data) => {
                    console.log('Fetched proposals:', data);
                    if (Array.isArray(data)) {
                        setProposals(data);
                    } else {
                        setProposals([]);
                    }
                })
                .catch((error) => {
                    console.error('Error:', error);
                    setProposals([]);
                });
        }
    };

    const handleProposalClick = (proposal) => {
        fetch('http://localhost:8080/api/sendProposal', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                fromId: userId,
                toId: proposal.toId, // 수정 필요: 올바른 toId 값으로 교체
                photoUrl: proposal.photoUrl,
                goodName: proposal.goodName,
                goodDetail: proposal.goodDetail,
                goodRequire: proposal.goodRequire,
                term: proposal.term,
                payWay: proposal.payWay,
                pay: proposal.pay,
            }),
        })
            .then((response) => response.json())
            .then((data) => {
                console.log('Send proposal created:', data);
                // 필요에 따라 추가 작업 수행
            })
            .catch((error) => {
                console.error('Error:', error);
            });
    };

    return (
        <>
            <Modal isOpen={isOpen} toggle={toggle} size="lg">
                <ModalHeader toggle={toggle}>제안서 목록</ModalHeader>
                <ModalBody>
                    <ListGroup>
                        {proposals.length > 0 ? (
                            proposals.map((proposal) => (
                                <ListGroupItem key={proposal.id} onClick={() => handleProposalClick(proposal)}>
                                    <img
                                        src={`http://localhost:8080/api/proposals/images/${proposal.photoUrl}`}
                                        alt={proposal.goodName}
                                        className="proposal-image"
                                    />
                                    <div>이름: {proposal.goodName}</div>
                                </ListGroupItem>
                            ))
                        ) : (
                            <div>제안서가 없습니다.</div>
                        )}
                    </ListGroup>
                </ModalBody>
                <ModalFooter>
                    <Button color="primary" onClick={toggleContractModal}>
                        제안서 생성
                    </Button>
                    <Button color="secondary" onClick={toggle}>
                        닫기
                    </Button>
                </ModalFooter>
            </Modal>

            <ContractModal
                isOpen={isContractModalOpen}
                toggle={toggleContractModal}
                email={userId}
                refreshProposals={refreshProposals}
            />
        </>
    );
};

export default ProposalListModal;
